<script setup lang="ts">import InsuranceSelectionMobile from '../../components/InsuranceSelectionMobile.vue';import InsuranceApplicationMobile from '../../components/InsuranceApplicationMobile.vue';import {goodsForInsurance} from '@kuaixie/ui/useInsurance';
import AddressSelectionMobile from '../../components/AddressSelectionMobile.vue';
import {useV15CreateIntentPage} from '../../stores/useV15CreateIntentPage';
const {prefs,id,trip,categories,loading,busy,error,done,itemName,itemSpec,quantity,unit,categoryId,unitPrice,note,contactName,contactPhone,address,expectDate,insurance,unitLabels,unitIndex,goodsAmount,insuranceQuoteId,quote,pending,load,submit,selectAddress,unitChange,categoryChange,formatAmount,mobilePreferenceStyle} = useV15CreateIntentPage();
</script>
<template><scroll-view scroll-y class="original-subpage" :class="{'kx-dark':prefs.theme==='dark','kx-care':prefs.care}" :style="mobilePreferenceStyle(prefs)"><text class="op-back" @click="uni.navigateBack()">‹ {{$t('m2.mobile.back')}}</text><view class="op-title">{{$t('v15.createIntent')}}</view>
<view v-if="loading" class="op-empty">{{$t('account.loading')}}</view><view v-else-if="error&&!trip" class="op-error">{{error}}<button class="op-action op-secondary" @click="load">{{$t('common.retry')}}</button></view>
<template v-else-if="trip"><view class="op-card"><view class="op-card-title">{{$t('v15.tripInfo')}}</view><view class="op-row"><text>{{trip.destination}}</text><text>{{trip.depart_date||''}}</text></view></view>
<view class="op-card"><text class="v15-label">{{$t('v15.itemName')}} *</text><input :disabled="busy||!!pending||!!done" class="v15-field" v-model="itemName" maxlength="120"/><text class="v15-label">{{$t('v15.itemSpec')}}</text><input :disabled="busy||!!pending||!!done" class="v15-field" v-model="itemSpec" maxlength="160"/>
<view class="v15-flow-row"><view><text class="v15-label">{{$t('v15.quantity')}} *</text><input :disabled="busy||!!pending||!!done" class="v15-field" type="number" v-model="quantity"/></view><view><text class="v15-label">{{$t('v15.unit')}}</text><picker :disabled="busy||!!pending||!!done" :range="unitLabels.map(k=>$t(k))" :value="unitIndex" @change="unitChange"><view class="v15-selector">{{$t(unitLabels[unitIndex])}} ⌄</view></picker></view></view>
<text class="v15-label">{{$t('v15.category')}}</text><picker :disabled="busy||!!pending||!!done" v-if="categories.length" :range="categories.map(c=>c.name)" :value="Math.max(0,categories.findIndex(c=>String(c.id)===categoryId))" @change="categoryChange"><view class="v15-selector">{{categories.find(c=>String(c.id)===categoryId)?.name||$t('v15.category')}} ⌄</view></picker>
<text class="v15-label">{{$t('v15.unitPrice')}} *</text><input :disabled="busy||!!pending||!!done" class="v15-field" type="digit" v-model="unitPrice"/><text class="v15-label">{{$t('v15.note')}}</text><textarea :disabled="busy||!!pending||!!done" class="v15-area" v-model="note" maxlength="1024"/>
<text class="v15-label">{{$t('v15.expectDate')}}</text><picker :disabled="busy||!!pending||!!done" mode="date" @change="expectDate=String($event.detail.value)"><view class="v15-selector">{{expectDate||$t('v15.expectDate')}} ⌄</view></picker></view>
<view class="op-card"><AddressSelectionMobile v-if="!busy&&!pending&&!done" @selected="selectAddress"/><text class="v15-section">{{$t('v15.receiver')}}</text><text class="v15-label">{{$t('v15.receiver')}} *</text><input :disabled="busy||!!pending||!!done" class="v15-field" v-model="contactName" maxlength="64"/><text class="v15-label">{{$t('v15.phoneContact')}} *</text><input :disabled="busy||!!pending||!!done" class="v15-field" v-model="contactPhone" maxlength="24"/><text class="v15-label">{{$t('v15.address')}} *</text><textarea :disabled="busy||!!pending||!!done" class="v15-area" v-model="address" maxlength="500"/></view>
<view class="op-card"><text class="v15-section">{{$t('v15.insurance')}}</text><view class="v15-choices"><view class="v15-choice" :class="{selected:insurance==='yes'}" @click="!busy&&!pending&&!done&&(insurance='yes')">{{$t('v15.insure')}}</view><view class="v15-choice" :class="{selected:insurance==='waived'}" @click="!busy&&!pending&&!done&&(insurance='waived')">{{$t('v15.waive')}}</view></view><InsuranceSelectionMobile v-if="insurance==='yes'&&!pending&&!done" subject-type="trip" :subject-id="id" :item-name="itemName" :declared-value="goodsForInsurance(unitPrice,Number(quantity))" @selected="insuranceQuoteId=$event?.id"/><view class="op-row"><text>{{$t('v15.amount')}}</text><text>{{Number.isFinite(goodsAmount)?formatAmount(goodsAmount):'—'}}</text></view><template v-if="quote"><view class="op-row"><text>{{$t('order.serviceFee')}}</text><text>{{formatAmount(quote.serviceFee,quote.currency)}}</text></view><view class="op-row"><text>{{$t('order.insurancePremium')}}</text><text>{{formatAmount(quote.insurancePremium,quote.currency)}}</text></view><view class="op-row"><text>{{$t('order.buyerEscrow')}}</text><text>{{formatAmount(quote.buyerEscrow,quote.currency)}}</text></view></template><view class="op-muted">{{$t(pending?'order.pendingRetry':'order.escrowNotice')}}</view><button class="op-action" :disabled="busy||!!done" @click="submit">{{$t(pending?'v15.retry':'v15.submit')}}</button></view>
<InsuranceApplicationMobile v-if="done" :order-id="done"/><view v-if="done" class="op-banner" @click="uni.navigateTo({url:'/pages/intent-detail/index?id='+encodeURIComponent(done)})">{{$t('v15.intentCreated')}} · {{done}} ›</view><view v-if="error" class="op-error">{{error}}</view>
</template></scroll-view></template>
